    const feature = {
        type: 'Feature',
        properties: {},
        geometry: {
            type: 'MultiPolygon',
            coordinates: HEX_OUTLINE_1
        }
    };

    assert.deepEqual(
        featureToH3Set(feature, DEFAULT_RES),
        hexagons,
        'featureToH3Set matches expected'
