test('featureToH3Set - resolution 10', assert => {
    const parentHex = '89283082837ffff';
    const vertices = h3.cellToBoundary(parentHex, true);
    const feature = {
        type: 'Feature',
        properties: {},
        geometry: {
            type: 'Polygon',
            coordinates: [
                [
                    vertices[2],
                    vertices[3],
                    vertices[4],
                    vertices[5],
                    vertices[0],
                    vertices[1],
                    vertices[2]
                ]
            ]
        }
    };
    const resolution = 10;

    const expected = h3.uncompactCells([parentHex], resolution).sort();

    assert.equal(expected.length, 7, 'Got expected child hexagons');

    assert.deepEqual(
        featureToH3Set(feature, resolution).sort(),
        expected,
        'featureToH3Set matches expected'
    );

    assert.end();
});

