test('h3SetToFeatureCollection', assert => {
    const hexagons = ['89283085507ffff', '892830855b3ffff'];

    const expected = {
        type: 'FeatureCollection',
        features: [
            {
                type: 'Feature',
                id: hexagons[0],
                properties: {},
                geometry: {
                    type: 'Polygon',
                    coordinates: HEX_OUTLINE_1
                }
            },
            {
                type: 'Feature',
                id: hexagons[1],
                properties: {},
